<?php $products=$this->getVar('paymentProducts',array());$csrf=htmlspecialchars($this->getVar('paymentCsrf',''),ENT_QUOTES,'UTF-8'); ?>
<section class="payment-workbench"><header><p class="eyebrow">PAYMENT CONFIGURATION</p><h1>Products and prices</h1><p>A price version is permanent once created. Publish a new version when a price changes.</p></header><?php if($this->getVar('paymentMessage','')):?><div class="success"><?=htmlspecialchars($this->getVar('paymentMessage'))?></div><?php endif;?><?php if($this->getVar('paymentError','')):?><div class="error"><?=htmlspecialchars($this->getVar('paymentError'))?></div><?php endif;?><div class="payment-admin-grid"><article class="payment-card"><h2>New product</h2><form method="post" action="<?=$this->uri(array('action'=>'createproduct'))?>"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><label>Product code<input name="code" required></label><label>Name<input name="name" required></label><label>Purpose<select name="purpose_type"><option value="membership">Membership</option><option value="private_course">Private course</option></select></label><label>Tier or course code<input name="purpose_id" required></label><label>Billing period<select name="billing_period"><option value="monthly">Monthly</option><option value="annual">Annual</option><option value="one_off">One-off</option></select></label><label>Access duration in months<input type="number" name="duration_months" min="1" max="120"></label><button class="button" type="submit">Create product</button></form></article><article class="payment-card"><h2>Add a price version</h2><form method="post" action="<?=$this->uri(array('action'=>'addprice'))?>"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><label>Product<select name="product_id"><?php foreach($products as $p):?><option value="<?=htmlspecialchars($p['id'])?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></label><label>Version code<input name="version_code" placeholder="2026-08" required></label><label>Amount in cents<input type="number" name="amount_minor" min="1" required></label><label>Currency<input name="currency" value="ZAR" maxlength="3" required></label><label>Effective from<input name="effective_from" value="<?=date('Y-m-d H:i:s')?>" required></label><label>Effective until (optional)<input name="effective_until"></label><button class="button" type="submit">Publish price</button></form></article></div><article class="payment-card"><h2>Saved products</h2><table><thead><tr><th>Product</th><th>Purpose</th><th>Period</th><th>Current price</th><th>Versions</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><strong><?=htmlspecialchars($p['name'])?></strong><br><small><?=htmlspecialchars($p['code'])?></small></td><td><?=htmlspecialchars($p['purpose_type'].' · '.$p['purpose_id'])?></td><td><?=htmlspecialchars($p['billing_period'])?></td><td><?php $cp=$p['current_price']??null; echo $cp?htmlspecialchars($cp['currency']).' '.number_format($cp['amount_minor']/100,2):'Not priced';?></td><td><?=count($p['prices']??array())?></td></tr><?php endforeach;?></tbody></table></article></section>
